using System;
using System.IO;
using System.Threading;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using VenusWorld;
namespace Planetary.EditorTools {
public static class PlanetVolumeValidation {
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Settle(PlanetFlight f){for(int i=0;i<60000;i++){f.Excavation.Tick();if(i>2&&f.Excavation.Volume.Settled){Physics.SyncTransforms();return;}Thread.Sleep(1);}throw new Exception("Volume did not settle");}
 static PlanetFlight live;static DVector liveDirection;static double liveSurface,liveStarted,lastUpdate,nextRecord;static int livePhase;static string liveEvidence;static int liveCamera,liveScene;
 public static void StartLive(){
  live=UnityEngine.Object.FindFirstObjectByType<PlanetFlight>();Require(Application.isPlaying&&live,"Play planet flight first");live.Initialize();live.VerificationInputLock=true;live.StopCruise();liveCamera=live.View.GetInstanceID();liveScene=live.gameObject.scene.handle;liveDirection=live.Position.Normalized;liveSurface=live.Sampler.SurfaceRadius(liveDirection);liveStarted=lastUpdate=EditorApplication.timeSinceStartup;nextRecord=0;livePhase=0;liveEvidence=Path.Combine(Application.dataPath,"../Documentation/volume-live-validation.txt");File.WriteAllText(liveEvidence,"Live Venus descent and 140 m underground traversal. Input locked for reproducibility.\n");live.BeginDescent();EditorApplication.update-=LiveTick;EditorApplication.update+=LiveTick;
 }
 static void LiveTick(){if(!live||!Application.isPlaying){EditorApplication.update-=LiveTick;return;}
  try{double now=EditorApplication.timeSinceStartup,dt=Math.Min(.05,now-lastUpdate);lastUpdate=now;Require(now-liveStarted<240,"Live volume test timed out");Require(live.View.GetInstanceID()==liveCamera&&live.gameObject.scene.handle==liveScene,"Same camera and scene underground");
   if(now>nextRecord){File.AppendAllText(liveEvidence,$"phase={livePhase}; altitude={live.Altitude:F3}; meshChunks={live.Excavation.Volume.ResidentCount}; cachePages={live.Excavation.Store.CachedPages}\n");nextRecord=now+3;}
   if(livePhase==0&&live.Altitude<=2.01&&live.Excavation.Ready){for(double depth=-4;depth<=146;depth+=2)live.Excavation.Store.Sculpt(liveDirection*(liveSurface-depth),3,false);livePhase=1;live.View.transform.rotation=Quaternion.LookRotation(-liveDirection.Float,Vector3.up);}
   else if(livePhase==1&&live.Excavation.Volume.Settled){double depth=liveSurface-live.Position.Magnitude;double step=Math.Min(140-depth,8*dt);if(step>0){var next=live.Excavation.ResolveMovement(live.Position,live.Position-liveDirection*step);live.SetPositionForVerification(next);}if(depth>=139.99){live.Excavation.Save();live.Excavation.Store.Reload();Require(live.Excavation.Store.Sample(live.Position)>.8,"Deep tunnel persists after reload");live.BeginAscent();Require(live.CruiseTarget==0,"Orbit control cannot teleport through rock");livePhase=2;}}
   else if(livePhase==2&&live.Excavation.Volume.Settled){var tangent=Vector3.ProjectOnPlane(Vector3.up,liveDirection.Float).normalized;Require(Physics.Raycast(Vector3.zero,tangent,out var hit,8)&&hit.distance>.5,"Live collidable tunnel wall at 140 m");Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(Application.dataPath,"../Library/TerrainBridge/preview.png"),Path.Combine(Application.dataPath,"../Documentation/volume-deep-tunnel.png"),true);File.AppendAllText(liveEvidence,"PASS: travelled continuously below old depth floor to 140 m; saved/reloaded tunnel; wall collider; no surface snap or underground orbit teleport.\n");livePhase=3;}
   else if(livePhase==3&&live.Excavation.Volume.Settled){double distance=liveSurface+2-live.Position.Magnitude;double step=Math.Min(distance,12*dt);if(step>0)live.SetPositionForVerification(live.Excavation.ResolveMovement(live.Position,live.Position+liveDirection*step));if(distance<.01){File.AppendAllText(liveEvidence,"PASS: returned through the same tunnel to the surface without changing scene or camera.\n");live.StopCruise();live.VerificationInputLock=false;EditorApplication.update-=LiveTick;Debug.Log("LIVE PLANET INTERIOR VALIDATION PASSED");}}
  }catch(Exception ex){live.StopCruise();live.VerificationInputLock=false;EditorApplication.update-=LiveTick;File.AppendAllText(liveEvidence,"FAIL: "+ex+"\n");Debug.LogException(ex);}
 }
 public static void BatchVerify(){
  string evidence=Path.GetFullPath(Path.Combine(Application.dataPath,"../Library/TerrainBridge/volume-validation.txt"));Directory.CreateDirectory(Path.GetDirectoryName(evidence));string scratch=Path.Combine(Application.temporaryCachePath,"volume-test-"+Guid.NewGuid().ToString("N"));
  var small=new PlanetSampler(128,128,false,0,0,42);var store=new PlanetDensityStore(small,scratch);
  Require(store.Sample(new DVector(0,0,0))<0,"Centre is solid and finite");Require(VolumeMesher.Build(new VolumeKey(0,0,0),store.Snapshot(new VolumeKey(0,0,0))).vertices.Length==0,"Unmined interior has no artificial boundary faces");
  for(double x=134;x>=-134;x-=2)store.Sculpt(new DVector(x,.25,.25),3,false);
  for(double x=134;x>=-134;x-=.25)Require(store.Sample(new DVector(x,.25,.25))>.8,"Unbroken full diameter tunnel, including centre");
  Require(store.Sample(new DVector(0,5,0))<0,"Tunnel retains rock walls");store.Save();
  var reloaded=new PlanetDensityStore(small,scratch);for(double x=130;x>=-130;x-=.5)Require(reloaded.Sample(new DVector(x,.25,.25))>.8,"Full tunnel survives save/load");
  // Force eviction beyond the 128-page cache, then revisit edited positive and negative coordinates.
  for(int i=0;i<200;i++)reloaded.Sample(new DVector(i*32,300,0));Require(reloaded.CachedPages<=128,"Bounded density page cache");Require(reloaded.Sample(new DVector(-16,.25,.25))>.8&&reloaded.Sample(new DVector(16,.25,.25))>.8,"Evicted chunks reload across signed boundaries");
  VenusData.Load();var venus=new PlanetSampler(6051800,6051000,true,800,.25,173);var deep=new PlanetDensityStore(venus,Path.Combine(scratch,"venus"));var d=VenusData.Direction(-7.5,303);double surface=venus.SurfaceRadius(d);
  foreach(double depth in new[]{100d,1000,50000,1000000,3000000,surface-1,surface,surface+1,surface+venus.SurfaceRadius(d*(-1))-100}){var p=d*(surface-depth);Require(double.IsFinite(deep.Sample(p)),"Finite density through centre");deep.Sculpt(p,3,false);Require(deep.Sample(p)>.8,"Mineable full-scale depth "+depth);var key=VolumeKey.At(p);var geometry=VolumeMesher.Build(key,deep.Snapshot(key));Require(geometry.vertices.Length>0,"Interior cavity mesh at "+depth);}
  deep.Save();var deepReload=new PlanetDensityStore(venus,Path.Combine(scratch,"venus"));Require(deepReload.Sample(new DVector(0,0,0))>.8,"Planet centre excavation persists");
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var definition=ScriptableObject.CreateInstance<PlanetDefinition>();definition.name="ThroughPlanetValidation";definition.radiusMetres=128;definition.elevationDatum=128;definition.useMagellan=false;definition.proceduralRelief=0;definition.detailAmplitude=0;definition.atmosphereHeight=0;definition.cloudHeight=0;definition.terrainMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Planetary/Surface.mat");definition.seed=Guid.NewGuid().GetHashCode();
  var flight=new GameObject("Through planet validation").AddComponent<PlanetFlight>();flight.planet=definition;flight.Initialize();int camera=flight.View.GetInstanceID(),scene=flight.gameObject.scene.handle;
  for(double x=134;x>=-134;x-=2)flight.Excavation.Store.Sculpt(new DVector(x,.25,.25),3,false);
  flight.SetPositionForVerification(new DVector(134,.25,.25));Settle(flight);int maxNodes=0;bool captured=false;
  for(int i=0;i<268;i++){var desired=flight.Position+new DVector(-1,0,0);Settle(flight);var next=flight.Excavation.ResolveMovement(flight.Position,desired);Require((next-desired).Magnitude<.00001,"Continuous movement through excavated tunnel at "+desired.x);flight.SetPositionForVerification(next);maxNodes=Math.Max(maxNodes,flight.Excavation.Volume.ResidentCount);Require(flight.View.GetInstanceID()==camera&&flight.gameObject.scene.handle==scene,"Same camera/scene through centre");
   if(!captured&&Math.Abs(flight.Position.x)<.1){Settle(flight);var ray=new Ray(Vector3.zero,Vector3.up);Require(Physics.Raycast(ray,out var hit,8),"Collidable tunnel wall at planet centre");Require(hit.distance>1&&hit.distance<4,"Correct centre tunnel wall depth");flight.View.transform.rotation=Quaternion.LookRotation(Vector3.left,Vector3.up);Excavation.EditorTools.TerrainBridge.Capture();File.Copy(Path.Combine(Path.GetDirectoryName(evidence),"preview.png"),Path.Combine(Path.GetDirectoryName(evidence),"volume-centre.png"),true);var blocked=flight.Excavation.ResolveMovement(flight.Position,flight.Position+new DVector(0,8,0));Require((blocked-flight.Position).Magnitude<3,"Movement cannot pass through unmined rock");captured=true;}
  }
  Require(flight.Position.x<=-134,"Reached opposite exterior");Require(maxNodes<=flight.planet.excavationMeshBudget+27,"Bounded streamed chunk count");flight.Excavation.Save();File.WriteAllText(evidence,$"PASS: complete 268 m test-world traversal from outside one side, through centre, to opposite exterior; same camera/scene, persistent full tunnel, collision against walls, no artificial chunk caps, signed chunk seams, bounded cache/stream.\\nPASS: full-size Venus excavation/mesh probes at 100 m, 1 km, 50 km, 1000 km, 3000 km, centre, across centre and opposite side.\\nPeak resident mesh chunks: {maxNodes}. Density cache cap: 128 pages. Full 12,100 km Venus tunnel was not excavated end-to-end in this test.\\n".Replace("\\n","\n"));Debug.Log("PLANET INTERIOR VALIDATION PASSED");flight.Excavation.DisposeResources();flight.Tiles.Dispose();UnityEngine.Object.DestroyImmediate(flight.gameObject);
 }
}
}
